import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_SIZE": 32, "warp_size": 32},
        ),
    ],
    key=["N"],
)
@triton.jit
def _layer_norm_best_kernel(
    X_ptr,
    Y_ptr,
    W_ptr,
    B_ptr,
    M,
    N,
    eps,
    BLOCK_SIZE: tl.constexpr,
    warp_size: tl.constexpr,
):
    row = tl.program_id(0)
    row_start = row.to(tl.int64) * N

    _sum = tl.zeros([BLOCK_SIZE], dtype=tl.float32)
    _sum_sq = tl.zeros([BLOCK_SIZE], dtype=tl.float32)
    for off in range(0, N, BLOCK_SIZE):
        cols = off + tl.arange(0, BLOCK_SIZE)
        mask = cols < N
        x = tl.load(X_ptr + row_start + cols, mask=mask, other=0.0).to(tl.float32)
        _sum += x
        _sum_sq += x * x
    mean = tl.sum(_sum, axis=0) / N
    var = tl.sum(_sum_sq, axis=0) / N - mean * mean
    rstd = 1.0 / tl.sqrt(var + eps)

    for off in range(0, N, BLOCK_SIZE):
        cols = off + tl.arange(0, BLOCK_SIZE)
        mask = cols < N
        x = tl.load(X_ptr + row_start + cols, mask=mask, other=0.0).to(tl.float32)
        w = tl.load(W_ptr + cols, mask=mask, other=1.0).to(tl.float32)
        b = tl.load(B_ptr + cols, mask=mask, other=0.0).to(tl.float32)
        y = (x - mean) * rstd * w + b
        tl.store(Y_ptr + row_start + cols, y.to(tl.bfloat16), mask=mask)


class Model(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super(Model, self).__init__()
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape)
        self._moved = False

    def _move_params(self, device):
        self.w_flat = (
            self.ln.weight.data.to(device, dtype=torch.bfloat16).contiguous().flatten()
        )
        self.b_flat = (
            self.ln.bias.data.to(device, dtype=torch.bfloat16).contiguous().flatten()
        )
        self._eps = self.ln.eps
        self._norm_n = 1
        for s in self.ln.normalized_shape:
            self._norm_n *= s
        self._moved = True

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not self._moved:
            self._move_params(x.device)
        x = x.contiguous()
        orig_shape = x.shape
        N = self._norm_n
        M = x.numel() // N
        x_flat = x.view(M, N)
        y_flat = torch.empty_like(x_flat)
        grid = (M,)
        _layer_norm_best_kernel[grid](
            x_flat,
            y_flat,
            self.w_flat,
            self.b_flat,
            M,
            N,
            self._eps,
        )
        return y_flat.view(orig_shape)
